#ifndef LCD_DUMP_CAPTURE_H
#define LCD_DUMP_CAPTURE_H

/*
 * Bus traffic of the original firmware, decoded from lcd_dump.sr (repository root, sigrok, 10 MHz, 9256 samples;
 * D0 CS, D1 RST, D2 A0, D3 SCK, D4 SDA). SPI mode 3, MSB first, one CS frame per byte, 91 frames, RST high.
 * The slice holds one complete RAM write: 3 address commands with A0 = 0, then 88 data bytes with A0 = 1.
 * Commands 0xB2 0x08 0x12 select page 2, column 40 (0x28); 40 + 88 = 128 columns.
 */

#include <stdint.h>

#define LCD_DUMP_PAGE 2U
#define LCD_DUMP_COLUMN 40U
#define LCD_DUMP_COMMAND_COUNT 3U
#define LCD_DUMP_DATA_COUNT 88U

static const uint8_t lcd_dump_commands[LCD_DUMP_COMMAND_COUNT] = {0xB2U, 0x08U, 0x12U};

static const uint8_t lcd_dump_data[LCD_DUMP_DATA_COUNT] = {
    0x00U, 0x00U, 0x00U, 0x00U, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x00U, 0x00U,
    0x00U, 0x00U, 0x00U, 0x00U, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x00U, 0x00U, 0x00U, 0x00U,
    0x00U, 0x00U, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x3CU, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U,
    0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U,
    0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U,
    0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x3CU,
};

#endif /* LCD_DUMP_CAPTURE_H */
